export const LANGUAGE_LOCALE_MAP: Record<string, string> = {
  hi: 'hi-IN',
  en: 'en-IN',
  mr: 'mr-IN',
  gu: 'gu-IN',
  bn: 'bn-IN',
  ta: 'ta-IN',
  te: 'te-IN',
  kn: 'kn-IN',
  or: 'or-IN',
};

export function getLocaleForLanguage(lang?: VoiceLanguage): string {
  if (!lang) return 'hi-IN';
  const clean = lang.toLowerCase().trim();
  if (LANGUAGE_LOCALE_MAP[clean]) {
    return LANGUAGE_LOCALE_MAP[clean];
  }
  if (clean.includes('-')) {
    return clean;
  }
  return `${clean}-IN`;
}

