function toTitleCase(str: string): string {
  if (!str) return '';
  return str.toLowerCase().replace(/\b[a-z]/g, c => c.toUpperCase());
}

function transliterateTrainHindi(name: string): string {
  if (!name) return '';
  let res = name.trim();
  for (const [pattern, hi] of HINDI_TRANSLITERATIONS) {
    res = res.replace(pattern, hi);
  }
  return res;
}

function expandTrainEnglish(name: string): string {
  if (!name) return '';
  let res = name.trim();
  for (const [pattern, en] of ENGLISH_TRAIN_EXPANSIONS) {
    res = res.replace(pattern, en);
  }
  return toTitleCase(res);
}

function formatCoachHindi(coach: string): string {
  if (!coach) return '';
  return coach
    .replace(/^B/i, 'बी ')
    .replace(/^S/i, 'एस ')
    .replace(/^A/i, 'ए ')
    .replace(/^H/i, 'एच ')
    .replace(/^M/i, 'एम ')
    .replace(/^C/i, 'सी ')
    .replace(/^D/i, 'डी ')
    .replace(/^G/i, 'जी ')
    .replace(/^GEN/i, 'जनरल ')
    .trim();
}

function cleanStationHi(stn: string): string {
  if (!stn) return '';
  let str = stn.replace(/\s*\([A-Z0-9]+\)\s*/gi, ' ').trim();
  str = str.replace(/\b(?:JN\.?|JUNCTION|CANTT\.?|CITY|TERMINUS|CENTRAL)\b/gi, '').trim();
  str = str.replace(/\s+/g, ' ').trim();

  let res = str;
  for (const [pattern, hi] of HINDI_TRANSLITERATIONS) {
    res = res.replace(pattern, hi);
  }
  return res.trim();
}

function cleanStationEn(stn: string): string {
  if (!stn) return '';
  const clean = stn
    .replace(/CHHATRAPATI SHIVAJI MAHARAJ TERMINUS|CSMT|CST/gi, 'Mumbai')
    .replace(/\s+(?:JN\.?|JUNCTION|CANTT\.?|CITY|TERMINUS|CENTRAL)\b/gi, '')
    .trim();
  return toTitleCase(clean);
}

