    const rate2 = 1.0;

    const items = [
      { text: part1Text, rate: rate1 },
      { text: part2Text, rate: rate2 }
    ];

    const fullAdviceText = `${part1Text} ${part2Text}`;
    this.lastSpokenText = fullAdviceText;
    if (targetLang === 'en') {
      this.lastEnglishText = fullAdviceText;
    }

    const chunks = [part1Text, part2Text].filter(Boolean);
    this.speakChunks(chunks, fullAdviceText, targetLang, targetGender, onEnd);
