  /**
   * Speak Railway Operational News / Cancellation Summary Bulletin
   */
  speakCancellationSummary(
    options: NewsCancellationSummaryOptions,
    lang?: VoiceLanguage,
    gender?: VoiceGender,
    onEnd?: () => void
  ): void {
    this.stop();
    const targetLang = lang || this.getLanguage();
    const targetGender = gender || this.getGender();

    const { totalAffected, fullyCancelled = 0, partiallyCancelled = 0, bulletinDate } = options;

    const formattedDateEn = formatVoiceBulletinDate(bulletinDate, 'en');
    const datePhraseEn = formattedDateEn ? `for ${formattedDateEn}, ` : '';
    const part1TextEn = `According to the latest railway operational bulletin ${datePhraseEn}a total of ${totalAffected} train services are affected.`;
    const part2TextEn = `This includes ${fullyCancelled} fully cancelled trains and ${partiallyCancelled} partially cancelled services. Please verify your train's live status and alternative connections on Trayago before heading to the station.`;

    const itemsEn = [
      { text: part1TextEn, rate: 1.0 },
      { text: part2TextEn, rate: 1.0 }
    ];

    const formattedDateHi = formatVoiceBulletinDate(bulletinDate, 'hi');
    const datePhraseHi = formattedDateHi ? `${formattedDateHi} के लिए ` : '';
    const part1TextHi = `भारतीय रेल द्वारा जारी ताज़ा परिचालन बुलेटिन के अनुसार... ${datePhraseHi}कुल ${totalAffected} ट्रेनों का परिचालन प्रभावित हुआ है।`;
    const part2TextHi = `इसमें से ${fullyCancelled} ट्रेनें पूरी तरह से रद्द हैं, और ${partiallyCancelled} ट्रेनें आंशिक रूप से रद्द की गई हैं। यात्रा शुरू करने से पहले, टियागो पर अपनी ट्रेन का लाइव स्टेटस और नया समय ज़रूर चेक कर लें।`;

    const itemsHi = [
      { text: part1TextHi, rate: 0.98 },
      { text: part2TextHi, rate: 1.0 }
    ];

    if (this.isNativePlatform()) {
      const fullText = targetLang === 'hi' ? `${part1TextHi} ${part2TextHi}` : `${part1TextEn} ${part2TextEn}`;
      const langCode = targetLang === 'hi' ? 'hi-IN' : 'en-IN';
      const fallbackItems = targetLang === 'hi' ? itemsHi : itemsEn;
      const char = this.getCharacter(targetGender);
      this.speakNative(fullText, langCode, 1.0, char.pitch || 1.12, targetGender, onEnd).then((ok) => {
        if (!ok) {
          if (this.isSupported()) {
            console.warn('[VOICE] Native TTS failed, falling back to Web Speech sequence for cancellation summary');
            this.speakViaWebSpeechSequence(fallbackItems, langCode, targetGender, onEnd);
          } else {
            console.warn('[VOICE] Neither engine available for cancellation summary');
          }
        }
      });
      return;
    }

    if (targetLang === 'hi') {
      if (this.isSupported()) {
        this.speakViaWebSpeechSequence(itemsHi, 'hi-IN', targetGender, onEnd);
        return;
      }
    } else {
      if (this.isSupported()) {
        this.speakViaWebSpeechSequence(itemsEn, 'en-IN', targetGender, onEnd);
        return;
      }
    }

    console.warn('[VOICE] Web Speech API not supported on this device/browser');
  }

