    const targetGender = gender || this.getGender();

    const tNo = options.trainNo ? String(options.trainNo).trim() : '';
    const tNoSpaced = tNo ? formatTrainNumberForVoice(tNo) : '';
    const tNameRaw = (options.trainName || '')
      .replace(/#\d+/g, '')
      .replace(/\b\d{5}\b/g, '')
